import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
const root=path.resolve(import.meta.dirname,'..');
const source=path.join(root,'src/publications/gage-gop-2026');
const out=path.join(root,'public/vote-2026');
const data=JSON.parse(fs.readFileSync(path.join(root,'src/data/elections/2026/election-directory.json')));
const calendar=JSON.parse(fs.readFileSync(path.join(root,'src/data/elections/2026/voting-calendar.json')));
const judicial=JSON.parse(fs.readFileSync(path.join(root,'src/data/elections/2026/judicial-retention.json')));
const candidates=new Map(data.candidates.map(r=>[r.candidateId,r]));
const affiliations=new Map(data.affiliations.map(r=>[r.affiliationId,r]));
const offices=new Map(data.offices.map(r=>[r.officeId,r]));
const groups=new Map();
for(const row of data.candidacies){const aff=affiliations.get(row.affiliationId);if(row.electionStageGroup==='current-general-election'&&aff.label==='Republican'&&aff.sourceId){if(!groups.has(row.officeId))groups.set(row.officeId,[]);groups.get(row.officeId).push(row);}}
for(const rows of groups.values())rows.sort((a,b)=>(a.seat||'').localeCompare(b.seat||'')||candidates.get(a.candidateId).displayName.localeCompare(candidates.get(b.candidateId).displayName));
const h=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const sections=[['federal','Federal',['office-us-senator','office-us-house-district-3']],['state','State',['office-nebraska-governor','office-nebraska-secretary-of-state','office-nebraska-state-treasurer','office-nebraska-attorney-general','office-nebraska-state-auditor','office-nebraska-legislature-district-30','office-state-board-of-education-district-5']],['county','County',[1,3,5,7].map(n=>`office-gage-county-supervisor-district-${n}`).concat(['office-gage-county-assessor','office-gage-county-attorney','office-gage-county-clerk','office-gage-county-register-of-deeds','office-gage-county-sheriff','office-gage-county-surveyor','office-gage-county-treasurer'])]];
for(const [id,title,category] of [['schools','School boards','School Boards'],['cities','Cities & villages','Cities & Villages'],['townships','Township boards','Township Boards'],['districts','Other local districts','Other Local Districts']])sections.push([id,title,[...groups.keys()].filter(id=>offices.get(id).category===category).sort()]);
const included=[];
function renderOffice(id){const office=offices.get(id);let title=office.officeName.replace('Gage County ','').replace('Nebraska ','');if(id==='office-nebraska-governor')title='Governor';const contests=new Map();for(const r of groups.get(id)||[]){const ward=id==='office-beatrice-city-council'?r.seat:null;const key=ward?`${id}:${ward}`:id;if(!contests.has(key))contests.set(key,{rows:[],ward});contests.get(key).rows.push(r);}
return [...contests].map(([key,{rows,ward}])=>{const limit=ward?1:office.voteFor;return `<fieldset class="office" data-contest="${h(key)}" data-limit="${limit}"><legend>${h(title)}${ward?' · '+h(ward):''}</legend><p class="limit">${limit===1?'Vote for one':`Vote for up to ${limit}`}</p>${rows.map(r=>{included.push(r.candidacyId);return `<div class="candidate" data-candidacy="${h(r.candidacyId)}"><span class="ballot-oval" aria-hidden="true"></span><span class="name">${h(candidates.get(r.candidateId).displayName)}${r.filingMethod==='Declared write-in'?' <strong class="write-in-label">(write-in)</strong>':''}</span>${r.filingMethod==='Declared write-in'?'<span class="candidate-note">Write this name on the ballot’s write-in line and mark its oval.</span>':''}${affiliations.get(r.affiliationId).evidenceType==='reported-affiliation'?'<span class="candidate-note">Affiliation reported by Voter Information Project.</span>':''}</div>`;}).join('')}</fieldset>`;}).join('');}
const retentionHTML=`<section class="category retention" id="judicial-retention" aria-labelledby="retention-title"><h2 id="retention-title" tabindex="-1">${h(judicial.copy.heading)}</h2><p>${h(judicial.copy.introduction)}</p><p>${h(judicial.copy.instructions)}</p><p class="subtle">Listed for ballot reference. Inclusion does not recommend a Yes or No vote.</p>${judicial.data.courts.map(court=>`<section class="retention-court"><h3>${h(court.name)} · ${h(court.scope)}</h3>${judicial.data.questions.filter(q=>q.courtId===court.courtId).map(q=>`<article class="retention-question" data-retention="${h(q.questionId)}"><h4>${h(q.name)}</h4><p>${h(q.ballotQuestion)}</p><p>Six-year term · Ballot choices: ${q.choices.map(h).join(' or ')}</p><a href="${h(q.sources[0].url)}">Official retention list</a></article>`).join('')}</section>`).join('')}<p><a href="${h(judicial.data.processSource.url)}">How judicial retention works</a></p></section>`;
const candidateHTML=sections.map(([id,title,ids])=>`<section class="category" id="${id}" aria-labelledby="${id}-title"><h2 id="${id}-title" tabindex="-1">${h(title)}</h2><div class="office-grid">${ids.map(renderOffice).join('')}</div></section>`).join('\n');
const expected=[...groups.values()].flat().map(r=>r.candidacyId).sort();if(JSON.stringify(included.toSorted())!==JSON.stringify(expected))throw Error('Candidate inclusion mismatch');
fs.mkdirSync(path.join(out,'assets'),{recursive:true});fs.mkdirSync(path.join(out,'calendar'),{recursive:true});
for(const file of ['style.css','app.js','sticker-share.mjs'])fs.copyFileSync(path.join(source,'web',file),path.join(out,file));
const versionedFiles={};
for(const file of ['style.css','app.js']){const content=fs.readFileSync(path.join(out,file));const digest=crypto.createHash('sha256').update(content).digest('hex').slice(0,12);const ext=path.extname(file);const name=file.slice(0,-ext.length)+'.'+digest+ext;fs.writeFileSync(path.join(out,name),content);versionedFiles[file]=name;}
for(const file of ['facebook-preview.png','facebook-post-square.png','sticker.png','gop-logo.webp','icon-192.png','icon-512.png','apple-touch-icon.png'])fs.copyFileSync(path.join(source,'assets',file),path.join(out,'assets',file));
const downloads=[['gage-county-gop-2026-mobile-card.png','candidate-card.png'],['gage-county-gop-2026-mobile-card.pdf','candidate-card.pdf'],['gage-county-gop-2026-candidate-flyer.pdf','print-flyer.pdf']];
for(const [file,dest] of downloads)fs.copyFileSync(path.join(root,'output/pdf',file),path.join(out,'assets',dest));
const escapeICS=s=>s.replaceAll('\\','\\\\').replaceAll(';','\\;').replaceAll(',','\\,').replaceAll('\n','\\n');
function fold(line){let chunks=[],part='';for(const char of line){if(Buffer.byteLength(part+char)>73){chunks.push(part);part=' ';}part+=char;}return [...chunks,part].join('\r\n');}
const titles=['Early ballots begin mailing','Early in-person voting begins','Online and mail voter registration deadline','In-person registration and mail-ballot request deadline','Election Day: 8 AM-8 PM Central'];
function event(m,i){const next=new Date(`${m.date}T12:00:00Z`);next.setUTCDate(next.getUTCDate()+1);return ['BEGIN:VEVENT',`UID:gage-2026-${m.date}@local-civic-reference`,`DTSTAMP:${calendar.reviewedDate.replaceAll('-','')}T120000Z`,`DTSTART;VALUE=DATE:${m.date.replaceAll('-','')}`,`DTEND;VALUE=DATE:${next.toISOString().slice(0,10).replaceAll('-','')}`,`SUMMARY:${escapeICS(titles[i])}`,`DESCRIPTION:${escapeICS(m.description+'\nAll times Central. Source: '+calendar.source.url)}`,'TRANSP:TRANSPARENT','BEGIN:VALARM','TRIGGER:-P1D','ACTION:DISPLAY',`DESCRIPTION:${escapeICS(titles[i])}`,'END:VALARM','END:VEVENT'];}
function makeICS(events){return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Local Civic Reference//Gage Election Dates//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH',...events.flat(),'END:VCALENDAR'].map(fold).join('\r\n')+'\r\n';}
fs.writeFileSync(path.join(out,'_headers'),'/calendar/*\n  Content-Type: text/calendar; charset=utf-8\n  Content-Disposition: inline\n');
const events=calendar.milestones.map(event);fs.writeFileSync(path.join(out,'calendar/all-dates.ics'),makeICS(events));
calendar.milestones.forEach((m,i)=>fs.writeFileSync(path.join(out,`calendar/${m.date}.ics`),makeICS([events[i]])));
const edition=calendar.reviewedDate;
const displayDate=value=>new Intl.DateTimeFormat('en-US',{month:'long',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'));
const recordDate=displayDate(data.lastValidated);
const calendarDate=displayDate(calendar.reviewedDate);
const calendarOrigin=JSON.parse(fs.readFileSync(path.join(source,'publication.json'))).publicBaseUrl.replace(/\/$/,'');
function appleCalendar(file){return calendarOrigin.replace('https:','webcal:')+'/calendar/'+file;}
function googleCalendar(m,i){const next=new Date(m.date+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+1);const params=new URLSearchParams({action:'TEMPLATE',text:titles[i],dates:m.date.replaceAll('-','')+'/'+next.toISOString().slice(0,10).replaceAll('-',''),details:m.description+'\nAll times Central. Source: '+calendar.source.url,ctz:calendar.timeZone});return 'https://calendar.google.com/calendar/render?'+params;}
const socialTitle='2026 Republican candidate card · Gage County GOP';
const socialDescription='Browse candidates, save voting dates, and download the print or phone edition.';
const socialAlt='2026 Republican candidate card. Gage County GOP, Nebraska. Your candidates. Your voting dates. Ready to save and take with you. Illustration of the Gage County courthouse.';
const socialHash=crypto.createHash('sha256').update(fs.readFileSync(path.join(out,'assets/facebook-preview.png'))).digest('hex').slice(0,12);
const socialImage=calendarOrigin+'/assets/facebook-preview.png?v='+socialHash;
const socialMeta=`<link rel="canonical" href="${calendarOrigin}/"><meta property="og:type" content="website"><meta property="og:locale" content="en_US"><meta property="og:site_name" content="Gage County GOP"><meta property="og:url" content="${calendarOrigin}/"><meta property="og:title" content="${h(socialTitle)}"><meta property="og:description" content="${h(socialDescription)}"><meta property="og:image" content="${socialImage}"><meta property="og:image:secure_url" content="${socialImage}"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="${h(socialAlt)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${h(socialTitle)}"><meta name="twitter:description" content="${h(socialDescription)}"><meta name="twitter:image" content="${socialImage}"><meta name="twitter:image:alt" content="${h(socialAlt)}">`;
const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#172c47"><meta name="card-version" content="${edition}"><meta name="description" content="A phone-friendly 2026 Republican candidate reference for Gage County, with voting dates and downloadable PDFs."><title>2026 Candidate Card · Gage County GOP</title>${socialMeta}<link rel="manifest" href="./manifest.webmanifest"><link rel="apple-touch-icon" href="./assets/apple-touch-icon.png"><link rel="icon" href="./assets/icon-192.png"><link rel="stylesheet" href="./${versionedFiles['style.css']}"><script type="module" src="./${versionedFiles['app.js']}"></script></head><body><a class="skip" href="#candidates">Skip to candidates</a><main class="page"><header class="hero" id="top"><div class="brand"><img src="./assets/gop-logo.webp" alt="GOP" width="58" height="38"><div><strong>GAGE COUNTY GOP</strong><p class="eyebrow">NEBRASKA</p></div></div><h1>2026 Republican<br>candidate card</h1><p class="eyebrow">GENERAL ELECTION · NOVEMBER 3</p><p class="appeal">Take this with you to vote for Republican Party candidates.</p><p class="intro">Your address determines your ballot. Follow its offices, districts, and voting limits.</p><p class="source-date">Candidate records reviewed <time datetime="${data.lastValidated}">${recordDate}</time>. <a href="#about">Sources & scope</a></p></header><section class="category" id="save"><h2 tabindex="-1">Take this card with you</h2><p class="intro">Print the letter-size PDF or save the mobile PDF to your phone. Both include the full candidate list and separate judicial retention questions. The letter-size PDF has two pages.</p><div class="actions"><a class="button" href="./assets/candidate-card.pdf" download>Download mobile PDF</a><a class="button" href="./assets/print-flyer.pdf" download>Download letter-size PDF</a><button id="share" class="js-only" type="button" hidden>Share card link</button></div></section><nav class="quick-nav" aria-label="Card navigation"><p class="nav-title">On this card</p><div class="section-links">${sections.map(([id,title])=>`<a href="#${id}" data-section="${id}">${h(title)}</a>`).join('')}<a href="#judicial-retention" data-section="judicial-retention">Judicial retention</a><a href="#dates">Voting dates</a><a href="#save">Save &amp; share</a><a href="#voted">I voted sticker <svg class="voted-nav-check" aria-hidden="true" focusable="false" width="16" height="16" viewBox="0 0 16 16"><path d="m3 8 3 3 7-7" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg></a></div><label for="jump" class="skip">Jump to section</label><select id="jump" class="js-only" hidden><option value="">Jump to a section</option>${sections.map(([id,title])=>`<option value="${id}">${h(title)}</option>`).join('')}<option value="judicial-retention">Judicial retention</option><option value="dates">Voting dates</option></select><a href="#dates">Dates</a><a href="#save">Save card</a></nav><noscript><p class="intro">Candidate information and downloads work without JavaScript. Enable it to share the card link.</p></noscript><div id="candidates">${candidateHTML}</div>${retentionHTML}<section class="category" id="dates"><h2 tabindex="-1">Key voting dates</h2><p class="subtle">2026 · All times Central</p><a class="button" data-webcal="all-dates.ics" href="${appleCalendar('all-dates.ics')}">Subscribe in Apple Calendar · all dates</a><p class="subtle">Apple Calendar adds a separate, read-only calendar. For Google Calendar, add dates individually below. If an in-app browser blocks opening Calendar, open this card in Safari or Chrome.</p><a href="./calendar/all-dates.ics" download>Download all dates (.ics)</a><div class="date-grid">${calendar.milestones.map((m,i)=>`<article class="date"><h3><time datetime="${m.date}">${h(m.label)}</time></h3><p>${h(m.description).replaceAll('\n','<br>')}</p><div class="calendar-actions"><a class="button" href="${h(googleCalendar(m,i))}" target="_blank" rel="noopener" aria-label="Add ${h(m.label)} to Google Calendar">Google Calendar</a><a class="button" href="./calendar/${m.date}.ics" aria-label="Open ${h(m.label)} in Apple Calendar">Apple Calendar</a></div></article>`).join('')}</div><p class="subtle">Review and confirm dates in your calendar. Calendar files include a day-before reminder; Google Calendar uses your own reminder settings. Calendar actions need an internet connection. <a href="${h(calendar.source.url)}">Official election calendar</a></p></section><footer id="about"><a class="site-link" href="https://www.gagecountygop.org/">gagecountygop.org</a><p><strong>Provided by Gage County GOP</strong></p><p>Includes documented Republicans in nonpartisan races. Candidates with unconfirmed affiliations are omitted. Listing does not imply endorsement. This reference is not an official ballot.</p><p>Candidate source: Local Civic Reference. Candidate records reviewed ${recordDate}. <a href="https://partyreveal.com/">View candidate evidence and sources</a>. Calendar checked ${calendarDate}.</p><p>No account or analytics. Downloaded images and PDFs include the candidate list and separate judicial retention questions.</p><a href="#top">Back to top</a></footer><section id="voted" class="sticker-section" aria-labelledby="sticker-title"><h2 id="sticker-title">Voted? Display it proudly.</h2><p>After you vote, celebrate with your Gage County sticker.</p><button id="sticker-reveal" class="js-only" hidden type="button" aria-expanded="false" aria-controls="sticker-panel">I voted — get my sticker</button><div id="sticker-panel"><h3 id="sticker-message" tabindex="-1">Your “I voted!” sticker is ready.</h3><a href="./assets/sticker.png" target="_blank" rel="noopener" aria-label="Open I voted sticker image"><img class="voted-sticker" src="./assets/sticker.png" alt="I voted! Gage County, Nebraska, 2026. Navy brush lettering above an illustration of the Gage County courthouse and American flag." width="1254" height="1254" loading="lazy"></a><div class="actions"><button id="sticker-share" class="primary js-only" hidden type="button">Share sticker</button><a class="button" href="./assets/sticker.png" download="gage-county-i-voted-2026.png">Save sticker image</a></div><p id="sticker-status" class="status" role="status" aria-live="polite"></p><p class="subtle">Choose an app from your phone’s sharing menu. For Facebook, you can also save the image and add it to a post. On iPhone, open the image and touch and hold it to save to Photos.</p></div></section></main></body></html>`;
fs.writeFileSync(path.join(out,'index.html'),html);
fs.writeFileSync(path.join(out,'manifest.webmanifest'),JSON.stringify({id:'./',name:'Gage GOP Candidate Card',short_name:'Gage GOP',description:'2026 Gage County candidate reference',start_url:'./',scope:'./',display:'standalone',background_color:'#ffffff',theme_color:'#172c47',icons:[{src:'./assets/icon-192.png',sizes:'192x192',type:'image/png',purpose:'any'},{src:'./assets/icon-512.png',sizes:'512x512',type:'image/png',purpose:'any'}]},null,2));
const assets=['./','./index.html','./'+versionedFiles['style.css'],'./'+versionedFiles['app.js'],'./sticker-share.mjs','./manifest.webmanifest',...fs.readdirSync(path.join(out,'assets')).map(f=>'./assets/'+f),...fs.readdirSync(path.join(out,'calendar')).map(f=>'./calendar/'+f)];
const hash=crypto.createHash('sha256');for(const file of assets){hash.update(file);hash.update(fs.readFileSync(path.join(out,file==='./'?'index.html':file)));}const version=hash.digest('hex').slice(0,16);
fs.writeFileSync(path.join(out,'sw.js'),fs.readFileSync(path.join(source,'web/sw.template.js'),'utf8').replace('__CACHE__',JSON.stringify('gage-gop-card-'+version)).replace('__ASSETS__',JSON.stringify(assets)));
fs.writeFileSync(path.join(out,'build-info.json'),JSON.stringify({version,edition,candidateListings:included.length,distinctCandidates:new Set([...groups.values()].flat().map(r=>r.candidateId)).size,officeCount:groups.size,assets},null,2));
console.log(`Built ${included.length} candidate listings, ${calendar.milestones.length} calendar events and ${assets.length} offline assets in ${out}`);
